private BigDecimal validateAndComputeDose(List<DoseSegmentRequest> segments, LocalDateTime loanAt, LocalDateTime returnedAt) {
    if (segments.isEmpty() || segments.size() > 20) throw badRequest("剂量段数量须为 1 至 20 段");
    List<DoseSegmentRequest> sorted = segments.stream().sorted(Comparator.comparing(DoseSegmentRequest::startAt)).toList();
    BigDecimal total = BigDecimal.ZERO;
    LocalDateTime cursor = loanAt;
    for (DoseSegmentRequest seg : sorted) {
        if (seg.startAt() == null || seg.endAt() == null || seg.illuminanceLux() == null) throw badRequest("剂量段缺少必填字段");
        if (!seg.endAt().isAfter(seg.startAt())) throw badRequest("剂量段结束时刻须晚于起始时刻");
        if (seg.illuminanceLux().signum() < 0 || seg.illuminanceLux().scale() > 3) throw badRequest("照度须为非负且最多3位小数");
        if (!seg.startAt().equals(cursor)) throw badRequest("剂量段须互不重叠且完整覆盖实际借出至归还");
        BigDecimal minutes = BigDecimal.valueOf(Duration.between(seg.startAt(), seg.endAt()).toNanos())
                .divide(NANOS_PER_MINUTE, MathContext.DECIMAL128);
        total = total.add(seg.illuminanceLux().multiply(minutes));
        cursor = seg.endAt();
    }
    if (!cursor.equals(returnedAt)) throw badRequest("剂量段须完整覆盖至实际归还时刻");
    return total;
}
```
