        Instant t20 = BASE.plusSeconds(1200);

        // 缺段（null 与空列表）
        assertThat(returnLoan("alice", evidenceKey, uniqueKey("CMD"), loanKey, true, 1L, null)
                .getResponse().getStatus()).isEqualTo(400);
