        // 负照度 / 照度超过3位小数 / 结束不晚于开始
        assertThat(returnLoan("alice", evidenceKey, uniqueKey("CMD"), loanKey, true, 1L,
                List.of(segment(t0, t20, "-1"))).getResponse().getStatus()).isEqualTo(400);
        assertThat(returnLoan("alice", evidenceKey, uniqueKey("CMD"), loanKey, true, 1L,
